//! American College of Rheumatology source topics and version-specific linked assets.
use super::{common,Adapter,PlanRow};
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::{Fetched,Fetcher};
use crate::guidelines::html::{sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::HashSet;
use url::Url;
pub struct Acr;
fn catalog(html:&str,base:&Url)->Result<Vec<(String,String)>>{let d=Html::parse_document(html);let group=d.select(&sel("div[class^='styles_subCategory__']")).find(|e|e.select(&sel("h2")).any(|h|text_of(&h)=="Clinical Practice Guidelines")).context("ACR guideline topic group missing")?;let mut seen=HashSet::new();let mut out=vec![];for a in group.select(&sel("li a[href]")){let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let u=Url::parse(&url)?;if u.origin()!=base.origin()||!u.path().ends_with("-guideline"){continue;}let t=text_of(&a);if !t.is_empty()&&seen.insert(url.clone()){out.push((url,t))}}if out.is_empty(){bail!("ACR guideline topic group empty");}Ok(out)}
fn links(html:&str,base:&Url)->Result<Vec<(String,String,String)>>{let d=Html::parse_document(html);let mut seen=HashSet::new();let mut out=vec![];for a in d.select(&sel("a[href]")){let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let u=Url::parse(&url)?;if u.host_str()!=Some("assets.contentstack.io"){continue;}let path=u.path().to_lowercase();if !path.ends_with(".pdf")&&!path.ends_with(".docx"){continue;}let label=text_of(&a);let low=label.to_lowercase();let role=if low.contains("summary"){"summary"}else if low.contains("appendix")||low.contains("supplement"){"supplement"}else if low.contains("guideline"){"guideline"}else{"source_asset"};if seen.insert((url.clone(),role.to_string())){out.push((url,label,role.into()))}}if out.is_empty(){bail!("ACR topic has no recognised source-linked assets");}Ok(out)}
fn pdf_complete(f:&Fetched)->bool{f.is_pdf()&&f.body.iter().rev().take(2048).copied().collect::<Vec<_>>().windows(5).any(|x|x==b"FOE%%")}
fn unresolved(src:&SourceEntry,url:String,e:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("{}-unresolved",common::short_hash(&url)),url,title:None,rendition:None,version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for Acr{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let cat=f.get_ok(src.catalog_url.as_deref().context("ACR catalog missing")?).await?;let base=Url::parse(&cat.record.final_url)?;let mut rows=vec![];let mut deferred=vec![];for(url,title)in catalog(&cat.text(),&base)?{let page=match f.get_ok(&url).await{Ok(x)=>x,Err(e)=>{deferred.push(unresolved(src,url,format!("{e:#}")));continue;}};let b=Url::parse(&page.record.final_url)?;if b.origin()!=base.origin(){deferred.push(unresolved(src,url,"topic origin changed".into()));continue;}let assets=match links(&page.text(),&b){Ok(x)=>x,Err(e)=>{deferred.push(unresolved(src,url,format!("{e:#}")));continue;}};
  for(asset,label,role)in assets{if !Url::parse(&asset)?.path().to_lowercase().ends_with(".pdf"){deferred.push(unresolved(src,asset,"DOCX supplement requires source-specific mapping".into()));continue;}let pdf=match f.get_ok(&asset).await{Ok(x)if pdf_complete(&x)=>x,Ok(_)=>{deferred.push(unresolved(src,asset,"source asset is not a complete PDF".into()));continue;},Err(e)=>{deferred.push(unresolved(src,asset,format!("{e:#}")));continue;}};let key=common::short_hash(&asset);rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("{key}-{}",&pdf.record.sha256[..12]),url:asset,title:Some(title.clone()),rendition:Some("pdf".into()),version:None,extra:json!({"work_key":key,"source_role":role,"source_label":label,"topic_url":url,"topic_sha256":page.record.sha256,"pdf_sha256":pdf.record.sha256,"catalog_fetch":cat.record})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}let rem=limit.map(|n|n.saturating_sub(rows.len())).unwrap_or(usize::MAX);rows.extend(deferred.into_iter().take(rem));Ok(rows)}
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=row.extra["discovery_error"].as_str(){bail!("ACR source unresolved: {e}");}let topic=row.extra["topic_url"].as_str().context("topic URL missing")?;let p=f.get_ok(topic).await?;if row.extra["topic_sha256"].as_str().is_some_and(|x|x!=p.record.sha256){bail!("ACR topic changed since discovery");}if !links(&p.text(),&Url::parse(&p.record.final_url)?)?.iter().any(|(u,_,_)|u==&row.url){bail!("ACR topic no longer links PDF");}let pdf=f.get_ok(&row.url).await?;if !pdf_complete(&pdf){bail!("ACR PDF incomplete");}if row.extra["pdf_sha256"].as_str().is_some_and(|x|x!=pdf.record.sha256){bail!("ACR PDF changed since discovery");}let(blocks,mut warnings,_)=super::static_list::blocks_for(&pdf,None,0).await?;if blocks.is_empty(){bail!("ACR PDF yielded no content");}warnings.push("Version-specific source asset; generic PDF conversion does not verify recommendation strength/certainty, PICO links, multirow tables, figures or page order. Supplements and publisher renditions have separate roles and rights.".into());let mut fetches=vec![];if let Ok(r)=serde_json::from_value::<crate::guidelines::doc::FetchRecord>(row.extra["catalog_fetch"].clone()){fetches.push(r)}fetches.push(p.record);fetches.push(pdf.record);Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["work_key"].as_str().map(String::from),title:row.title.clone().unwrap_or_default(),url:row.url.clone(),item_type:row.extra["source_role"].as_str().map(String::from),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("Source PDF, article and supplements require independent rights assessment.".into()),..Default::default()},search_metadata:json!({"topic_url":topic,"source_label":row.extra["source_label"]}),blocks,fetches,warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const A:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/acr/catalog-1.html"));const B:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/acr/catalog-2.html"));#[test]fn real_catalog_identifies_rheumatoid_topic_without_invented_asset(){let base=Url::parse("https://rheumatology.org/Practice-Quality/Clinical-Support/Clinical-Practice-Guidelines").unwrap();let rows=catalog(&format!("{A}{B}"),&base).unwrap();assert!(rows.iter().any(|(u,t)|u=="https://rheumatology.org/rheumatoid-arthritis-guideline"&&t=="Rheumatoid Arthritis"));assert!(catalog("<html/>",&base).is_err());}}

#[cfg(all(test, feature = "guideline-fixtures"))] mod source_topic_test {
 use super::*;
 const A:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/acr/ra-topic-1.html"));
 const B:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/acr/ra-topic-2.html"));
 #[test] fn actual_ra_topic_keeps_edition_and_appendix_roles(){
  let u=Url::parse("https://rheumatology.org/rheumatoid-arthritis-guideline").unwrap();let links=links(&format!("{A}{B}"),&u).unwrap();
  assert!(links.iter().any(|(u,l,r)|l.contains("2021 American College of Rheumatology Guideline")&&r=="guideline"&&u.ends_with("ra-guideline-2021.pdf")));
  assert!(links.iter().any(|(_,l,r)|l.contains("Evidence Report 2021")&&r=="supplement"));
  assert!(links.iter().any(|(_,l,r)|l.contains("Executive Summary")&&r=="summary"));
  assert!(links.iter().any(|(u,l,_)|l.contains("2015 American College")&&u.ends_with("ra-guideline-2015.pdf")));
 }
}
